				))
				run("add", ".")
				run("commit", "-m", "Checkpoint: abcdef012345")
				run("branch", "-f", paths.MetadataBranchName, "temp-orphan")
				run("checkout", "main")
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			bareDir := initBareWithMetadataBranch(t)
